// NOTE: Assertions have been autogenerated by utils/update_cc_test_checks.py
// RUN: %clang_cc1 -triple riscv32 -target-feature +zfinx -target-feature +zhinx \
// RUN:     -target-feature +xpulpv -target-feature +xpulpfvec -O1 -emit-llvm %s -o - \
// RUN:     | FileCheck %s

// Task 20/F049 (backlog B149): GAP9 packed half <-> packed int16 conversions
// with GAP9 GCC's prototypes (all four use the signed vector of shorts) and
// the vfcvt.{x,xu}.h / vfcvt.h.{x,xu} semantics: round with frm (llvm.rint),
// saturate to 16 bits, NaN gives 0x7fff / 0xffff.

typedef _Float16 v2h __attribute__((vector_size(4)));
typedef short v2s __attribute__((vector_size(4)));
typedef unsigned short v2u __attribute__((vector_size(4)));

// CHECK-LABEL: @test_v2hftov2hi(
// CHECK-NEXT:  entry:
// CHECK-NEXT:    [[TMP0:%.*]] = bitcast i32 [[X_COERCE:%.*]] to <2 x half>
// CHECK-NEXT:    [[TMP1:%.*]] = tail call <2 x half> @llvm.rint.v2f16(<2 x half> [[TMP0]])
// CHECK-NEXT:    [[TMP2:%.*]] = tail call <2 x i16> @llvm.fptosi.sat.v2i16.v2f16(<2 x half> [[TMP1]])
// CHECK-NEXT:    [[TMP3:%.*]] = fcmp uno <2 x half> [[TMP0]], zeroinitializer
// CHECK-NEXT:    [[TMP4:%.*]] = select <2 x i1> [[TMP3]], <2 x i16> splat (i16 32767), <2 x i16> [[TMP2]]
// CHECK-NEXT:    [[TMP5:%.*]] = bitcast <2 x i16> [[TMP4]] to i32
// CHECK-NEXT:    ret i32 [[TMP5]]
//
v2s test_v2hftov2hi(v2h x) { return __builtin_pulp_v2hftov2hi(x); }

// CHECK-LABEL: @test_v2hftov2hi_u(
// CHECK-NEXT:  entry:
// CHECK-NEXT:    [[TMP0:%.*]] = bitcast i32 [[X_COERCE:%.*]] to <2 x half>
// CHECK-NEXT:    [[TMP1:%.*]] = tail call <2 x half> @llvm.rint.v2f16(<2 x half> [[TMP0]])
// CHECK-NEXT:    [[TMP2:%.*]] = tail call <2 x i16> @llvm.fptoui.sat.v2i16.v2f16(<2 x half> [[TMP1]])
// CHECK-NEXT:    [[TMP3:%.*]] = fcmp uno <2 x half> [[TMP0]], zeroinitializer
// CHECK-NEXT:    [[TMP4:%.*]] = select <2 x i1> [[TMP3]], <2 x i16> splat (i16 -1), <2 x i16> [[TMP2]]
// CHECK-NEXT:    [[TMP5:%.*]] = bitcast <2 x i16> [[TMP4]] to i32
// CHECK-NEXT:    ret i32 [[TMP5]]
//
v2s test_v2hftov2hi_u(v2h x) { return __builtin_pulp_v2hftov2hi_u(x); }

// CHECK-LABEL: @test_v2hitov2hf(
// CHECK-NEXT:  entry:
// CHECK-NEXT:    [[TMP0:%.*]] = bitcast i32 [[X_COERCE:%.*]] to <2 x i16>
// CHECK-NEXT:    [[TMP1:%.*]] = sitofp <2 x i16> [[TMP0]] to <2 x half>
// CHECK-NEXT:    [[TMP2:%.*]] = bitcast <2 x half> [[TMP1]] to i32
// CHECK-NEXT:    ret i32 [[TMP2]]
//
v2h test_v2hitov2hf(v2s x) { return __builtin_pulp_v2hitov2hf(x); }

// CHECK-LABEL: @test_v2hitov2hf_u(
// CHECK-NEXT:  entry:
// CHECK-NEXT:    [[TMP0:%.*]] = bitcast i32 [[X_COERCE:%.*]] to <2 x i16>
// CHECK-NEXT:    [[TMP1:%.*]] = uitofp <2 x i16> [[TMP0]] to <2 x half>
// CHECK-NEXT:    [[TMP2:%.*]] = bitcast <2 x half> [[TMP1]] to i32
// CHECK-NEXT:    ret i32 [[TMP2]]
//
v2h test_v2hitov2hf_u(v2s x) { return __builtin_pulp_v2hitov2hf_u(x); }

// The SDK's FloatDefines.h use: Cvt_v2u_v2h passes a v2u (lax vector
// conversion to v2s, as in GCC); Cvt_v2h_v2u casts the result to v2u.
// CHECK-LABEL: @test_sdk_v2u_v2h(
// CHECK-NEXT:  entry:
// CHECK-NEXT:    [[TMP0:%.*]] = bitcast i32 [[X_COERCE:%.*]] to <2 x i16>
// CHECK-NEXT:    [[TMP1:%.*]] = uitofp <2 x i16> [[TMP0]] to <2 x half>
// CHECK-NEXT:    [[TMP2:%.*]] = bitcast <2 x half> [[TMP1]] to i32
// CHECK-NEXT:    ret i32 [[TMP2]]
//
v2h test_sdk_v2u_v2h(v2u x) { return (v2h)__builtin_pulp_v2hitov2hf_u(x); }

// CHECK-LABEL: @test_sdk_v2h_v2u(
// CHECK-NEXT:  entry:
// CHECK-NEXT:    [[TMP0:%.*]] = bitcast i32 [[X_COERCE:%.*]] to <2 x half>
// CHECK-NEXT:    [[TMP1:%.*]] = tail call <2 x half> @llvm.rint.v2f16(<2 x half> [[TMP0]])
// CHECK-NEXT:    [[TMP2:%.*]] = tail call <2 x i16> @llvm.fptoui.sat.v2i16.v2f16(<2 x half> [[TMP1]])
// CHECK-NEXT:    [[TMP3:%.*]] = fcmp uno <2 x half> [[TMP0]], zeroinitializer
// CHECK-NEXT:    [[TMP4:%.*]] = select <2 x i1> [[TMP3]], <2 x i16> splat (i16 -1), <2 x i16> [[TMP2]]
// CHECK-NEXT:    [[TMP5:%.*]] = bitcast <2 x i16> [[TMP4]] to i32
// CHECK-NEXT:    ret i32 [[TMP5]]
//
v2u test_sdk_v2h_v2u(v2h x) { return (v2u)__builtin_pulp_v2hftov2hi_u(x); }
